namespace MRS;
internal sealed class Js8Bridge : IDisposable
{
 private TcpClient? client;private CancellationTokenSource? cancel;private readonly SemaphoreSlim writer=new(1);internal event Action<string>? Received;internal event Action<string>? Status;
 internal async Task Connect(int port){Dispose();var next=new TcpClient{NoDelay=true};var c=new CancellationTokenSource();cancel=c;client=next;await next.ConnectAsync(IPAddress.Loopback,port,c.Token);_=Read(next,c.Token);}
 private async Task Read(TcpClient connection,CancellationToken token){try{var line=new List<byte>();byte[] buffer=new byte[2048];while(!token.IsCancellationRequested){int count=await connection.GetStream().ReadAsync(buffer,token);if(count==0)throw new IOException("JS8Call disconnected");for(int i=0;i<count;i++){byte b=buffer[i];if(b==10){if(!token.IsCancellationRequested&&ReferenceEquals(client,connection))Received?.Invoke(Encoding.UTF8.GetString(line.ToArray()).TrimEnd('\r'));line.Clear();}else{if(line.Count>=16384)throw new IOException("JS8Call API line exceeded limit");line.Add(b);}}}}catch(OperationCanceledException){}catch(Exception ex){if(!token.IsCancellationRequested&&ReferenceEquals(client,connection))Status?.Invoke(ex.Message);}finally{connection.Dispose();}}
 internal static string Command(string type,string value="",object? parameters=null)=>JsonSerializer.Serialize(new Dictionary<string,object?>{{"type",type},{"value",value},{"params",parameters??new{}}})+"\n";
 internal async Task Send(string type,string value="",object? parameters=null){await writer.WaitAsync();try{if(client==null||cancel==null)throw new IOException("Connect to JS8Call first");await client.GetStream().WriteAsync(Encoding.UTF8.GetBytes(Command(type,value,parameters)),cancel.Token);}finally{writer.Release();}}
 public void Dispose(){cancel?.Cancel();client?.Dispose();client=null;cancel=null;}
}
